CREATE OR REPLACE FUNCTION public.handle_venue_music_request_vote_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.recalculate_venue_music_request_votes(old.request_id);
    return old;
  else
    perform public.recalculate_venue_music_request_votes(new.request_id);
    return new;
  end if;
end;
$function$

